      "decisive_positive_evidence": [
        {
          "evidence_id": "E0109",
          "explanation": "The Purbachal plot-allocation chronology and alleged file removal create a concrete self-dealing concern tied to Hasina's family and office, even though the reporting remains allegation-stage."
        },
        {
          "evidence_id": "E0110",
          "explanation": "The ACC filing and abuse-of-power allegations against Hasina and Saima Wazed strengthen the personal-integrity concern because they directly connect office power to family benefit."
        },
        {
          "evidence_id": "E0098",
          "explanation": "The Digital Security Act investigation of a corruption reporter shows retaliation pressure around scrutiny of misconduct, even if the immediate complainant was not Hasina personally."
        }
      ],
      "decisive_negative_evidence": [
        {
          "evidence_id": "E0094",
          "explanation": "The technocratic appointment of Bangladesh Bank governor Abdur Rouf Talukder is a genuine merit-signaling counterexample that keeps the score above the low end."
        },
        {
          "evidence_id": "E0108",
          "explanation": "Hasina's defensive BBC interview comments are direct ruler statements, but they read as denial or deflection rather than an admission of wrongdoing."
        }
      ],
      "inherited_baseline_and_constraints": "No structured local priors were collected. Bangladesh-wide repression or corruption context is treated only as background unless the evidence ties it to Hasina's own statements, appointments, family benefit, or tolerated retaliation.",
      "ruler_attribution": "Mixed and partly indirect: the dossier shows direct family-benefit allegations and a retaliation environment under Hasina's government, plus one merit-based appointment and one defensive public statement. The strongest personal nexus is allegation-heavy rather than adjudication-heavy.",
      "supported_lenses": [
        "7B.2",
        "7B.3",
        "7B.4",
        "7B.5",
        "7B.6",
        "7B.7",
        "7B.8",
        "7B.9",
        "7B.10"
      ],
      "missing_or_weak_lenses": [
        "7B.1"
      ],
      "contrary_evidence": [
        {
          "evidence_id": "E0094",
          "explanation": "One technocratic appointment undercuts a pure patronage reading."
        },
        {
          "evidence_id": "E0108",
          "explanation": "The quoted interview is defensive, not a confession or correction."
        }
      ],
      "source_mix": "Official appointment material, NGO reporting, and later media reports on allegations. Strongest where the record includes dated official actions or concrete allegation chronology; weaker where the nexus is indirect or unresolved.",
      "structured_prior_summary": "Local priors unavailable in this experiment; judgment rests on the embedded chapter projection, quoted excerpts, and explicit gap notes only.",
      "chapter_rationale": "Hasina scores low on personal integrity but not at the floor because the dossier contains concrete family-benefit allegations, a corruption-reporter retaliation episode, and a later abuse-of-power case, yet it stops short of a clean adjudicated finding that she personally ordered or profited from every disputed act. The favorable side is narrow: one technocratic central-bank appointment and no direct court record of personal enrichment in the target year. The unfavorable side is stronger because the plot-allocation story, ACC filing, and Digital Security Act retaliation all point toward office power being used around family and patronage concerns. Those items are still not the same as a final judicial finding, so they lower confidence more than they force the score to the absolute bottom. The record supports a score in the low-to-mid 3s rather than a materially higher one because the personal-nexus evidence is substantial, repeated, and unresolved.",
      "lower_anchor_rejected": "A score of 2 or below would require stronger proof that personal extraction or deliberate deception was central and clearly proven. This file has serious allegations, but not enough direct adjudication to justify the floor.",
      "higher_anchor_rejected": "A score of 5 or above would overread one merit-based appointment and a defensive public interview as if they outweighed repeated family-benefit and retaliation concerns. The dossier is mixed, but not cleanly honest.",
      "manual_review_required": false,
      "manual_review_reason_type": null,
      "manual_review_reason": null,
