        "upper": 4.0
      },
      "decisive_positive_evidence": [
        {
          "evidence_id": "E0083",
          "explanation": "Bolsonaro's repeated unsupported attacks on Brazil's voting system are direct public deception claims about a core democratic institution."
        },
        {
          "evidence_id": "E0085",
          "explanation": "His continuing fraud suspicions and refusal to disclose a military report reinforce a pattern of selective opacity around the election."
        },
        {
          "evidence_id": "E0093",
          "explanation": "The suspicious first-family financial transactions reported from Federal Police analysis create a concrete integrity concern tied to Bolsonaro's office network."
        },
        {
          "evidence_id": "E0106",
          "explanation": "The family-linked payments case deepens the personal- and household-benefit concern even though it remained under investigation."
        }
      ],
      "decisive_negative_evidence": [
        {
          "evidence_id": "E0107",
          "explanation": "The ANA leadership appointments show at least some competent, professional staffing rather than a wholly loyalist cabinet pattern."
        },
        {
          "evidence_id": "E0108",
          "explanation": "The later INSS appointment also points to technocratic continuity in one part of the government."
        },
        {
          "evidence_id": "E0096",
          "explanation": "The Federal Police finding that there were no minimum evidentiary elements in one interference inquiry prevents this from collapsing into a universal corruption finding."
        }
      ],
      "inherited_baseline_and_constraints": "No structured local priors were collected. Brazil's noisy public sphere and heavy scandal volume are not treated as proof by themselves; only Bolsonaro-attributable statements, appointments, and family-finance concerns count.",
      "ruler_attribution": "Strong on direct public deception and on a family-finance nexus around the presidency; weaker on final adjudication because several financial concerns were still investigatory or denied. The dossier shows repeated tolerance of controversy rather than clean correction.",
      "supported_lenses": [
