      "contrary_evidence": [
        {
          "evidence_id": "E0107",
          "explanation": "A technocratic ANA appointment cuts against a pure cronyism score."
        },
        {
          "evidence_id": "E0096",
          "explanation": "One investigative inquiry did not produce minimum evidence of crime."
