      "decisive_negative_evidence": [
        {
          "evidence_id": "E0099",
          "explanation": "The adviser-influence inquiry around Vidiye Tshimanga puts the presidential orbit under a concrete corruption cloud."
        },
        {
          "evidence_id": "E0100",
          "explanation": "The taped-meeting reporting about Tshimanga and acting on the president's behalf keeps the personal-nexus question alive even though it remained contested."
        }
      ],
      "inherited_baseline_and_constraints": "No structured local priors were collected. Congo's broader governance problems are context only; the score is driven by Tshisekedi's own anti-corruption actions and the specific adviser-orbit allegations in his circle.",
      "ruler_attribution": "Moderately strong on ordered audits, leadership changes, and public instructions to clean up state assets. The negative side is that adviser-corruption allegations sit close to his office, but the file does not show a completed personal-benefit finding against him.",
      "supported_lenses": [
